cd /home/yamal/ALManac-food-data/raw/cofid/2021 && python3 - <<'EOF'
import openpyxl, warnings, collections
warnings.filterwarnings('ignore')
wb = openpyxl.load_workbook('McCance_Widdowsons_Composition_of_Foods_Integrated_Dataset_2021.xlsx', read_only=True, data_only=True)
print('== 1.1 Notes =='); 
for r in wb['1.1 Notes'].iter_rows(values_only=True):
    if r[0]: print('   ', str(r[0]).replace('\xa0',' '))
print('== List of tables ==')
for r in wb['List of tables'].iter_rows(values_only=True):
    if any(r): print('   ', r)
rows = [r for r in wb['1.3 Proximates'].iter_rows(min_row=4, values_only=True) if r and r[0]]
codes = collections.Counter(r[0] for r in rows)
print('duplicate codes:', [(c,n) for c,n in codes.items() if n>1])
for r in rows:
    if codes[r[0]]>1: print('   dup row:', r[:14])
grp = collections.Counter(r[3] for r in rows)
print('groups (%d):' % len(grp), sorted(grp.items()))
print('Q-group sample (alcohol col 23):')
for r in rows:
    if str(r[3]).startswith('Q'): print('   ', r[0], r[1][:50], '| grp', r[3], '| alc', r[23], '| kcal', r[12]); 
    if sum(1 for x in rows if str(x[3]).startswith('Q'))==0: break
EOF

