     1	import Foundation
     2	
     3	/// Folds text for alias matching: case, diacritics, punctuation and script
     4	/// variants removed, whitespace collapsed.
     5	///
     6	/// Arabic normalisation is explicit rather than left to a locale: an Arabic
     7	/// report writing إ where the catalog has ا must still match, and harakat and
     8	/// tatweel are decoration, not identity.
     9	public enum TextFold {
    10	    public static func fold(_ input: String) -> String {
    11	        var scalars = String.UnicodeScalarView()
    12	        for scalar in input.decomposedStringWithCanonicalMapping.lowercased().unicodeScalars {
    13	            if CharacterSet.nonBaseCharacters.contains(scalar) { continue }
