import Foundation

/// Licence groups from the Almanac collection reports and Processing Design v0.1 §1.
///
/// This is not documentation. It is the value that the bundle build asserts on,
/// so that shipping a restricted row is a build failure rather than a discovery
/// made after user data has accumulated against it.
public enum LicenceGroup: String, Codable, Sendable, CaseIterable, Hashable {
    /// Permissive core. Currently: USDA FoodData Central (CC0 1.0).
    case permissive = "A"
    /// Attribution required. CIQUAL, CoFID, Frida, AFCD.
    case attribution = "B"
    /// Share-alike on the derived database. Open Food Facts (ODbL).
    case shareAlike = "C"
    /// Restricted or unconfirmed rights. Quarantined.
    case restricted = "D"

    /// Whether rows in this group may be redistributed inside the app bundle.
    ///
    /// Processing Design v0.1 §1: putting a row in the bundle is redistributing
    /// it to every installing user, commercially, in a form they keep.
    public var isShippable: Bool {
        switch self {
        case .permissive, .attribution: return true
        case .shareAlike, .restricted: return false
        }
    }
}

public struct LicenceViolation: Error, CustomStringConvertible, Sendable {
    public let identifier: String
    public let group: LicenceGroup
    public init(identifier: String, group: LicenceGroup) {
        self.identifier = identifier
        self.group = group
    }
    public var description: String {
        "BUILD FAILURE: \(identifier) is licence group \(group.rawValue) and must never enter the bundle."
    }
}

public enum BundleGuard {
    /// Fails loudly rather than filtering silently. Processing Design v0.1 §5.
    public static func assertShippable<S: Sequence>(_ rows: S) throws
    where S.Element == (identifier: String, group: LicenceGroup) {
        for row in rows where !row.group.isShippable {
            throw LicenceViolation(identifier: row.identifier, group: row.group)
        }
    }
}

import Foundation

/// Processing Design v0.1 §3 — namespace, never renumber.
///
/// `usda:1105904`, `ciqual:1000`, `cofid:13-145`, `afcd:F002258`.
/// An Almanac-internal integer key is a private detail that must never replace
/// the publisher's identifier. Namespacing keeps a food traceable to its
/// publisher, lets two sources sit side by side, and — the point that matters —
/// keeps "remove a whole source" a one-line delete when a rights holder says no.
public struct SourceIdentifier: Codable, Sendable, Hashable, CustomStringConvertible {
    public let namespace: Namespace
    public let localID: String

    public enum Namespace: String, Codable, Sendable, CaseIterable, Hashable {
        case usda, ciqual, cofid, afcd, frida
        case openFoodFacts = "off"
        case sfda, wger, freeExerciseDB = "fedb", everkinetic, opentraining
        /// Rows Almanac owns outright. The only namespace Almanac may license
        /// independently.
        case almanac

        public var licenceGroup: LicenceGroup {
            switch self {
            case .usda, .almanac: return .permissive
            case .ciqual, .cofid, .afcd, .frida: return .attribution
            case .openFoodFacts: return .shareAlike
            case .sfda: return .restricted
            // Exercise sources carry per-entry licences (wger admits ODbL as a
            // possible value). They are never classified at source level —
            // exercise rows must carry their own group column.
            case .wger, .freeExerciseDB, .everkinetic, .opentraining: return .restricted
            }
        }
    }

    public init(namespace: Namespace, localID: String) {
        self.namespace = namespace
        self.localID = localID
    }

    public var description: String { "\(namespace.rawValue):\(localID)" }

    public init?(parsing text: String) {
        guard let sep = text.firstIndex(of: ":") else { return nil }
        let ns = String(text[text.startIndex..<sep])
        let rest = String(text[text.index(after: sep)...])
        guard let namespace = Namespace(rawValue: ns), !rest.isEmpty else { return nil }
        self.init(namespace: namespace, localID: rest)
    }
}

