        VALUES ('cofid:13-145', 'cofid', '13-145', 'B', 'DG', 'Vegetables, general', 'fixture');
        """)
    }

    private func insertValue(_ db: Database, amount: String, qualifier: String, cell: String,
                             ref: String = "cofid:13-145") throws {
